/* Is there a directory of this name beside us? Used to tell a shipped package from the
   development tree without a build flag; see the dir/content defaults. */
static bool dir_exists(const char* p)
{
    struct stat st;
    return p && *p && stat(p, &st) == 0 && (st.st_mode & S_IFDIR) != 0;
}

